<script lang="ts">
 import {onMount} from "svelte";
 import {type InferResponseType} from "hono/client";
 import {t,language,formatDate} from "#lib/i18n.svelte.ts";
 import {errorMessage} from "#lib/i18n/errors.ts";
 import {confirm} from "#lib/confirm.svelte.ts";
 import Button from "#lib/ui/Button.svelte";
 import Card from "#lib/ui/Card.svelte";
 import FloatField from "#lib/ui/FloatField.svelte";
 import {pulseApi,parseResponse} from "../../lib/api";
 import {panel} from "../../lib/panel.svelte";
 type Page=InferResponseType<typeof pulseApi.pages.$get,200>["pages"][number];
 type Monitor=InferResponseType<typeof pulseApi.monitors.$get,200>["monitors"][number];
 const incidentsGET=pulseApi.pages[":page"].incidents.$get;
 type Incident=InferResponseType<typeof incidentsGET,200>["incidents"][number];
 let pages=$state<Page[]>([]),monitors=$state<Monitor[]>([]),incidents=$state<Incident[]>([]),editing=$state<Page|null>(null),chosen=$state<Record<string,string>>({}),title=$state(""),slug=$state(""),busy=$state(false),error=$state<unknown>(null);
 let incidentTitle=$state(""),text=$state(""),incidentId=$state<string|null>(null),incidentStateValue=$state<"investigating"|"identified"|"monitoring"|"resolved">("investigating"),impact=$state<"operational"|"degraded"|"partial_outage"|"major_outage">("degraded");
 const writable=$derived(panel.usage?.readOnly===false);
 const validComponents=$derived(Object.values(chosen).every(v=>v.trim().length>0));
 async function run(fn:()=>Promise<void>){busy=true;error=null;try{await fn();}catch(e){error=e;}finally{busy=false;}}
 async function refresh(){pages=(await parseResponse(pulseApi.pages.$get())).pages;}
 async function edit(page:Page){editing=page;title=page.title;slug=page.slug;chosen=Object.fromEntries(page.components.map(c=>[c.monitorId,c.name]));incidents=(await parseResponse(incidentsGET({param:{page:page.id}}))).incidents;}
 function clear(){editing=null;title="";slug="";chosen={};incidents=[];incidentId=null;text="";}
 async function save(e:SubmitEvent){e.preventDefault();await run(async()=>{const components=Object.entries(chosen).map(([monitorId,name])=>({monitorId,name:name.trim()}));if(editing)await parseResponse(pulseApi.pages[":page"].$patch({param:{page:editing.id},json:{title,components,language:language()}}));else await parseResponse(pulseApi.pages.$post({json:{title,slug,components,language:language()}}));await refresh();clear();});}
 async function publish(page:Page){await run(async()=>{await parseResponse(pulseApi.pages[":page"].$patch({param:{page:page.id},json:{published:!page.published}}));await refresh();});}
 async function remove(page:Page){if(!await confirm({title:t("delete"),message:t("pulseDeletePage"),danger:true}))return;await run(async()=>{await parseResponse(pulseApi.pages[":page"].$delete({param:{page:page.id}}));await refresh();clear();});}
 async function incident(e:SubmitEvent){e.preventDefault();const page=editing;if(!page)return;await run(async()=>{if(incidentId)await parseResponse(pulseApi.pages[":page"].incidents[":incident"].updates.$post({param:{page:page.id,incident:incidentId},json:{body:text,state:incidentStateValue}}));else await parseResponse(pulseApi.pages[":page"].incidents.$post({param:{page:page.id},json:{title:incidentTitle,body:text,state:incidentStateValue,impact}}));incidentId=null;incidentTitle="";text="";incidents=(await parseResponse(incidentsGET({param:{page:page.id}}))).incidents;});}
 function toggleMonitor(id:string,checked:boolean){if(checked)chosen[id]="";else{const copy={...chosen};delete copy[id];chosen=copy;}}
 onMount(()=>{void run(async()=>{await refresh();monitors=(await parseResponse(pulseApi.monitors.$get())).monitors;});});
</script>
<h1 class="text-3xl font-bold">{t("pulsePages")}</h1><p class="my-4 text-sm text-neutral-500">{t("pulsePublicPrivacy")}</p>
{#if error}<p class="my-4 text-red-600" role="alert">{errorMessage(error)}</p>{/if}
{#if writable}<form class="my-6 grid gap-4" onsubmit={save}><div class="grid gap-4 sm:grid-cols-2"><FloatField id="page-title" label={t("pulsePageTitle")} required maxlength={100} bind:value={title}/><FloatField id="page-slug" label={t("pulseSlug")} required disabled={!!editing} maxlength={40} pattern="[a-z0-9]+(-[a-z0-9]+)*" bind:value={slug}/></div><fieldset class="grid gap-3"><legend class="mb-3 text-sm font-semibold">{t("pulseComponents")}</legend>{#each monitors as monitor(monitor.id)}<div class="flex flex-wrap items-center gap-3"><label class="flex items-center gap-2 text-sm"><input type="checkbox" checked={Object.hasOwn(chosen,monitor.id)} onchange={e=>toggleMonitor(monitor.id,e.currentTarget.checked)}/>{monitor.name}</label>{#if Object.hasOwn(chosen,monitor.id)}<FloatField id={`public-${monitor.id}`} label={t("pulsePublicName")} maxlength={80} required bind:value={chosen[monitor.id]}/>{/if}</div>{/each}</fieldset><div class="flex gap-2"><Button {busy} disabled={!validComponents}>{editing?t("save"):t("pulseCreatePage")}</Button>{#if editing}<Button type="button" variant="secondary" onclick={clear}>{t("cancel")}</Button>{/if}</div></form>{/if}
<div class="grid gap-3">{#each pages as page(page.id)}<Card><h2 class="font-bold">{page.title}</h2><a class="my-2 block break-all text-sm text-blup underline" href={`https://pulse.getblup.site/${page.slug}/`} target="_blank" rel="noopener noreferrer">pulse.getblup.site/{page.slug}/</a><div class="flex flex-wrap gap-2"><Button variant="secondary" onclick={()=>run(()=>edit(page))}>{t("pulseEdit")}</Button>{#if writable}<Button variant="secondary" onclick={()=>publish(page)}>{page.published?t("pulseUnpublish"):t("pulsePublish")}</Button>{/if}<Button variant="secondary" onclick={()=>remove(page)}>{t("delete")}</Button></div></Card>{:else}<p class="my-4 text-neutral-500">{t("pulseNoPages")}</p>{/each}</div>
{#if editing}<section class="mt-8"><h2 class="text-xl font-bold">{editing.title}: {t("pulseIncidents")}</h2>{#if writable}<form class="my-5 grid gap-4" onsubmit={incident}>{#if !incidentId}<FloatField id="incident-title" label={t("pulseIncidentTitle")} required maxlength={120} bind:value={incidentTitle}/>{/if}<label class="grid gap-2 text-sm">{t("pulseIncidentText")}<textarea class="min-h-28 rounded-lg border border-neutral-300 p-3 dark:border-neutral-700 dark:bg-neutral-900" required maxlength={2000} bind:value={text}></textarea></label><div class="flex flex-wrap gap-3"><select class="rounded-lg border p-3 dark:bg-neutral-900" aria-label={t("pulseIncidents")} bind:value={incidentStateValue}><option value="investigating">{t("pulseInvestigating")}</option><option value="identified">{t("pulseIdentified")}</option><option value="monitoring">{t("pulseMonitoring")}</option><option value="resolved">{t("pulseResolved")}</option></select>{#if !incidentId}<select class="rounded-lg border p-3 dark:bg-neutral-900" aria-label={t("pulseMonitors")} bind:value={impact}><option value="operational">{t("pulseOperational")}</option><option value="degraded">{t("pulseDegraded")}</option><option value="partial_outage">{t("pulsePartial")}</option><option value="major_outage">{t("pulseMajor")}</option></select>{/if}<Button {busy}>{incidentId?t("pulseUpdateIncident"):t("pulseNewIncident")}</Button></div></form>{/if}<div class="grid gap-3">{#each incidents as item(item.id)}<Card><h3 class="font-semibold">{item.title}</h3><p class="my-2 text-xs text-neutral-500">{formatDate(new Date(item.updatedAt))}</p>{#if writable}<Button variant="secondary" onclick={()=>{incidentId=item.id;incidentTitle=item.title;text="";}}>{t("pulseUpdateIncident")}</Button>{/if}</Card>{/each}</div></section>{/if}
